import React from 'react';
import { Tabs } from 'expo-router';
import FloatingTabBar from '@/components/FloatingTabBar';

const TABS = [
  {
    name: '(home)',
    title: 'Confronta',
    label: 'Confronta',
    icon: 'compare' as const,
    ios_icon_name: 'photo.on.rectangle.angled',
    android_material_icon_name: 'compare' as const,
    route: '/(tabs)/(home)' as any,
  },
  {
    name: 'history',
    title: 'Cronologia',
    label: 'Cronologia',
    icon: 'history' as const,
    ios_icon_name: 'clock.fill',
    android_material_icon_name: 'history' as const,
    route: '/(tabs)/history' as any,
  },
  {
    name: 'profile',
    title: 'Profilo',
    label: 'Profilo',
    icon: 'person' as const,
    ios_icon_name: 'person.fill',
    android_material_icon_name: 'person' as const,
    route: '/(tabs)/profile' as any,
  },
];

export default function TabLayout() {
  return (
    <Tabs
      tabBar={(props) => <FloatingTabBar {...props} tabs={TABS} />}
      screenOptions={{ headerShown: false }}
    >
      <Tabs.Screen name="(home)" options={{ headerShown: false }} />
      <Tabs.Screen name="history" options={{ headerShown: false }} />
      <Tabs.Screen name="profile" options={{ headerShown: false }} />
    </Tabs>
  );
}

import Constants from "expo-constants";
import { Platform } from "react-native";
import * as SecureStore from "expo-secure-store";
import { BEARER_TOKEN_KEY } from "@/lib/auth";

export const BACKEND_URL =
  Constants.expoConfig?.extra?.backendUrl ||
  "https://3az2ndteth9e6e3ftqke6u4yj9646gyu.app.specular.dev";

// Supabase Edge Functions base URL
const SUPABASE_URL = "https://fdnurgfcocmgknbmpjtd.supabase.co";
export const SUPABASE_FUNCTIONS_URL = `${SUPABASE_URL}/functions/v1`;

// Supabase anon key — used as Bearer token for edge function calls
const SUPABASE_ANON_KEY =
  "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZkbnVyZ2Zjb2NtZ2tuYm1wanRkIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzE3OTE5ODgsImV4cCI6MjA4NzM2Nzk4OH0.D1IbWjRau2GFOcHVBC6cJ80LxvRgct7X2r0BRA1Gr20";

export const getBearerToken = async (): Promise<string | null> => {
  try {
    if (Platform.OS === "web") {
      return localStorage.getItem(BEARER_TOKEN_KEY);
    } else {
      return await SecureStore.getItemAsync(BEARER_TOKEN_KEY);
    }
  } catch (error) {
    console.error("[API] Error retrieving bearer token:", error);
    return null;
  }
};

export const apiCall = async <T = any>(
  endpoint: string,
  options?: RequestInit
): Promise<T> => {
  const url = `${BACKEND_URL}${endpoint}`;
  console.log("[API] Calling:", url, options?.method || "GET");

  const response = await fetch(url, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options?.headers,
    },
  });

  if (!response.ok) {
    const text = await response.text();
    console.error("[API] Error response:", response.status, text);
    throw new Error(`API error: ${response.status} - ${text}`);
  }

  return response.json();
};

export const authenticatedApiCall = async <T = any>(
  endpoint: string,
  options?: RequestInit
): Promise<T> => {
  const token = await getBearerToken();
  if (!token) {
    throw new Error("Authentication token not found. Please sign in.");
  }
  return apiCall<T>(endpoint, {
    ...options,
    headers: {
      ...options?.headers,
      Authorization: `Bearer ${token}`,
    },
  });
};

export const apiGet = <T = any>(endpoint: string) =>
  apiCall<T>(endpoint, { method: "GET" });

export const apiPost = <T = any>(endpoint: string, data: any) =>
  apiCall<T>(endpoint, { method: "POST", body: JSON.stringify(data) });

export const authenticatedGet = <T = any>(endpoint: string) =>
  authenticatedApiCall<T>(endpoint, { method: "GET" });

export const authenticatedPost = <T = any>(endpoint: string, data: any) =>
  authenticatedApiCall<T>(endpoint, {
    method: "POST",
    body: JSON.stringify(data),
  });

export const authenticatedPut = <T = any>(endpoint: string, data: any) =>
  authenticatedApiCall<T>(endpoint, {
    method: "PUT",
    body: JSON.stringify(data),
  });

export const authenticatedPatch = <T = any>(endpoint: string, data: any) =>
  authenticatedApiCall<T>(endpoint, {
    method: "PATCH",
    body: JSON.stringify(data),
  });

export const authenticatedDelete = <T = any>(
  endpoint: string,
  data: any = {}
) =>
  authenticatedApiCall<T>(endpoint, {
    method: "DELETE",
    body: JSON.stringify(data),
  });

// ---------------------------------------------------------------------------
// Supabase Edge Function helpers
// Uses the Supabase anon key as Bearer token — works without Supabase auth.
// The edge functions identify the user via the Better Auth session cookie/header
// passed separately, or operate in anonymous mode.
// ---------------------------------------------------------------------------

const edgeFunctionCall = async <T = any>(
  fnName: string,
  options?: RequestInit
): Promise<T> => {
  const url = `${SUPABASE_FUNCTIONS_URL}/${fnName}`;
  console.log("[Edge] Calling:", url, options?.method || "GET");

  const response = await fetch(url, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
      ...options?.headers,
    },
  });

  if (!response.ok) {
    const text = await response.text();
    console.error("[Edge] Error response:", response.status, text);
    throw new Error(`Edge function error: ${response.status} - ${text}`);
  }

  return response.json();
};

/**
 * POST /functions/v1/compare
 * Analyze a face image and return celebrity lookalikes.
 * Sends { image_base64: string } with the Supabase anon key.
 */
export const compareFace = (image_base64: string) => {
  console.log("[Edge] Calling compare edge function with base64 image");
  return edgeFunctionCall<{
    matches?: { name: string; similarity: number; description: string }[];
    winner?: number;
    winnerSimilarity?: number;
    loserSimilarity?: number;
    reasons?: { feature: string; description: string; similarity?: number }[];
    summary?: string;
  }>("compare", { method: "POST", body: JSON.stringify({ image_base64 }) });
};

/**
 * GET /functions/v1/comparisons
 * Fetch the user's comparison history.
 */
export const getComparisons = () => {
  console.log("[Edge] Fetching comparison history");
  return edgeFunctionCall<{ comparisons: any[] }>("comparisons", {
    method: "GET",
  });
};

/**
 * DELETE /functions/v1/comparisons/:id
 * Delete a comparison.
 */
export const deleteComparison = (id: string) => {
  console.log("[Edge] Deleting comparison:", id);
  return edgeFunctionCall<{ success: boolean }>(`comparisons/${id}`, {
    method: "DELETE",
  });
};

import React, { useState } from 'react';
import * as ImagePicker from 'expo-image-picker';
import * as ImageManipulator from 'expo-image-manipulator';
import * as FileSystem from 'expo-file-system';
import { IconSymbol } from '@/components/IconSymbol';
import { LinearGradient } from 'expo-linear-gradient';
import { SafeAreaView } from 'react-native-safe-area-context';
import { colors } from '@/styles/commonStyles';
import { Stack, useRouter } from 'expo-router';
import { useAuth } from '@/contexts/AuthContext';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Image,
  TextInput,
  ActivityIndicator,
  Modal,
} from 'react-native';
import { compareFace } from '@/utils/api';

interface ImageData {
  uri: string;
  label: string;
}

function resolveImageSource(source: string | undefined) {
  if (!source) return { uri: '' };
  return { uri: source };
}

export default function HomeScreen() {
  const router = useRouter();
  const { signOut, user } = useAuth();

  const [mainImage, setMainImage] = useState<ImageData | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [errorModal, setErrorModal] = useState<{ visible: boolean; message: string }>({
    visible: false,
    message: '',
  });
  const [logoutModal, setLogoutModal] = useState(false);
  const [result, setResult] = useState<any>(null);

  const textColor = colors.text;
  const textSecondaryColor = colors.textSecondary;
  const cardColor = colors.card;
  const secondaryColor = colors.secondary;
  const accentColor = colors.accent;

  const showError = (message: string) => {
    setErrorModal({ visible: true, message });
  };

  const handleLogout = async () => {
    console.log('[Home] User confirmed logout');
    setLogoutModal(false);
    try {
      await signOut();
      console.log('[Home] User logged out successfully');
    } catch (error) {
      console.error('[Home] Logout error:', error);
    }
  };

  const compressAndEncode = async (uri: string): Promise<string> => {
    console.log('[Home] Compressing image:', uri);
    try {
      const manipResult = await ImageManipulator.manipulateAsync(
        uri,
        [{ resize: { width: 800 } }],
        { compress: 0.7, format: ImageManipulator.SaveFormat.JPEG, base64: true }
      );
      if (manipResult.base64) {
        console.log('[Home] Image compressed and encoded, length:', manipResult.base64.length);
        return manipResult.base64;
      }
      // Fallback: read file as base64
      const base64 = await FileSystem.readAsStringAsync(manipResult.uri, {
        encoding: FileSystem.EncodingType.Base64,
      });
      return base64;
    } catch (error) {
      console.error('[Home] Compression failed:', error);
      // Fallback: read original as base64
      const base64 = await FileSystem.readAsStringAsync(uri, {
        encoding: FileSystem.EncodingType.Base64,
      });
      return base64;
    }
  };

  const pickImage = async () => {
    console.log('[Home] User tapped pick image button');

    const permissionResult = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (permissionResult.granted === false) {
      showError("Devi consentire l'accesso alla galleria per caricare le foto.");
      return;
    }

    const pickerResult = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ['images'],
      allowsEditing: true,
      aspect: [3, 4],
      quality: 0.8,
    });

    if (!pickerResult.canceled && pickerResult.assets[0]) {
      console.log('[Home] Image selected:', pickerResult.assets[0].uri);
      setMainImage({ uri: pickerResult.assets[0].uri, label: '' });
      setResult(null);
    }
  };

  const takePhoto = async () => {
    console.log('[Home] User tapped take photo button');

    const permissionResult = await ImagePicker.requestCameraPermissionsAsync();
    if (permissionResult.granted === false) {
      showError("Devi consentire l'accesso alla fotocamera per scattare foto.");
      return;
    }

    const cameraResult = await ImagePicker.launchCameraAsync({
      allowsEditing: true,
      aspect: [3, 4],
      quality: 0.8,
    });

    if (!cameraResult.canceled && cameraResult.assets[0]) {
      console.log('[Home] Photo taken:', cameraResult.assets[0].uri);
      setMainImage({ uri: cameraResult.assets[0].uri, label: '' });
      setResult(null);
    }
  };

  const handleAnalyze = async () => {
    console.log('[Home] User tapped Analyze button');

    if (!mainImage) {
      showError('Carica una foto per continuare.');
      return;
    }

    if (!user) {
      showError("Devi effettuare l'accesso per analizzare le foto.");
      return;
    }

    setIsAnalyzing(true);
    setResult(null);

    try {
      console.log('[Home] Encoding image to base64...');
      const base64 = await compressAndEncode(mainImage.uri);

      console.log('[Home] Sending image to compare edge function...');
      const analysisResult = await compareFace(base64);
      console.log('[Home] Analysis result received:', analysisResult);

      setResult(analysisResult);
    } catch (error: any) {
      console.error('[Home] Error analyzing image:', error);
      let errorMessage = error?.message || "Si è verificato un errore durante l'analisi. Riprova.";

      if (error?.message?.includes('413') || error?.message?.toLowerCase().includes('payload too large')) {
        errorMessage = "L'immagine è troppo grande. Prova con una foto più piccola.";
      } else if (error?.message?.includes('Failed to fetch') || error?.message?.includes('Network')) {
        errorMessage = 'Errore di connessione. Verifica la tua connessione internet e riprova.';
      }

      showError(errorMessage);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleViewHistory = () => {
    console.log('[Home] User tapped View History button');
    router.push('/(tabs)/history');
  };

  const canAnalyze = !!mainImage && !isAnalyzing;
  const mainImageSource = resolveImageSource(mainImage?.uri);

  return (
    <LinearGradient
      colors={[colors.background, colors.backgroundDark]}
      style={styles.gradientContainer}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
    >
      <SafeAreaView style={styles.container} edges={['top']}>
        <Stack.Screen options={{ headerShown: false }} />

        <ScrollView
          style={styles.scrollView}
          contentContainerStyle={styles.scrollContent}
          showsVerticalScrollIndicator={false}
        >
          <View style={styles.header}>
            <View style={styles.emojiRow}>
              <Text style={styles.emoji}>🤔</Text>
              <Text style={styles.emoji}>👥</Text>
              <Text style={styles.emoji}>✨</Text>
            </View>
            <Text style={[styles.title, { color: textColor }]}>Chi ti somiglia?</Text>
            <Text style={[styles.subtitle, { color: textSecondaryColor }]}>
              Carica una foto e scopri a chi assomigli!
            </Text>
          </View>

          {/* Photo Section */}
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.sectionEmoji}>📸</Text>
              <Text style={[styles.sectionTitle, { color: secondaryColor }]}>La Tua Foto</Text>
            </View>

            <TouchableOpacity
              style={[styles.imageCard, { backgroundColor: cardColor, borderColor: secondaryColor }]}
              onPress={pickImage}
              activeOpacity={0.7}
              disabled={isAnalyzing}
            >
              {mainImage ? (
                <Image source={mainImageSource} style={styles.image} resizeMode="cover" />
              ) : (
                <View style={styles.imagePlaceholder}>
                  <IconSymbol
                    ios_icon_name="photo"
                    android_material_icon_name="add-photo-alternate"
                    size={48}
                    color={secondaryColor}
                  />
                  <Text style={[styles.placeholderText, { color: secondaryColor }]}>
                    Tocca per caricare
                  </Text>
                </View>
              )}
            </TouchableOpacity>

            <View style={styles.photoButtonsRow}>
              <TouchableOpacity
                style={[styles.photoButton, { backgroundColor: cardColor, borderColor: secondaryColor }]}
                onPress={pickImage}
                disabled={isAnalyzing}
                activeOpacity={0.8}
              >
                <IconSymbol ios_icon_name="photo.on.rectangle" android_material_icon_name="photo-library" size={20} color={secondaryColor} />
                <Text style={[styles.photoButtonText, { color: textColor }]}>Galleria</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.photoButton, { backgroundColor: cardColor, borderColor: accentColor }]}
                onPress={takePhoto}
                disabled={isAnalyzing}
                activeOpacity={0.8}
              >
                <IconSymbol ios_icon_name="camera.fill" android_material_icon_name="camera-alt" size={20} color={accentColor} />
                <Text style={[styles.photoButtonText, { color: textColor }]}>Fotocamera</Text>
              </TouchableOpacity>
            </View>

            {mainImage && (
              <TextInput
                style={[styles.labelInput, { backgroundColor: cardColor, color: textColor, borderColor: secondaryColor }]}
                placeholder="Chi sei? (opzionale)"
                placeholderTextColor={textSecondaryColor}
                value={mainImage.label}
                onChangeText={(text) => setMainImage({ ...mainImage, label: text })}
                editable={!isAnalyzing}
              />
            )}
          </View>

          {/* Analyze Button */}
          <TouchableOpacity
            style={[styles.analyzeButton, !canAnalyze && styles.analyzeButtonDisabled]}
            onPress={handleAnalyze}
            disabled={!canAnalyze}
            activeOpacity={0.8}
          >
            <LinearGradient
              colors={canAnalyze ? [secondaryColor, accentColor] : ['#666666', '#444444']}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 0 }}
              style={styles.analyzeGradient}
            >
              {isAnalyzing ? (
                <>
                  <ActivityIndicator color={colors.background} size="small" />
                  <Text style={[styles.analyzeButtonText, { color: colors.background }]}>
                    Analisi in corso...
                  </Text>
                </>
              ) : (
                <>
                  <Text style={styles.analyzeButtonEmoji}>🔍</Text>
                  <Text style={[styles.analyzeButtonText, { color: colors.background }]}>
                    Analizza Ora
                  </Text>
                </>
              )}
            </LinearGradient>
          </TouchableOpacity>

          {/* Results Section */}
          {result && (
            <View style={[styles.resultsSection, { backgroundColor: cardColor }]}>
              <Text style={[styles.resultTitle, { color: secondaryColor }]}>🏆 Risultati</Text>

              {result.matches && result.matches.length > 0 ? (
                result.matches.map((match: any, index: number) => {
                  const similarityNum = Number(match.similarity);
                  const similarityText = isNaN(similarityNum) ? String(match.similarity) : similarityNum.toFixed(1) + '%';
                  return (
                    <View key={index} style={[styles.matchCard, { borderColor: accentColor }]}>
                      <View style={styles.matchHeader}>
                        <Text style={[styles.matchName, { color: textColor }]}>{match.name}</Text>
                        <View style={[styles.matchBadge, { backgroundColor: accentColor }]}>
                          <Text style={[styles.matchSimilarity, { color: colors.background }]}>
                            {similarityText}
                          </Text>
                        </View>
                      </View>
                      {match.description ? (
                        <Text style={[styles.matchDescription, { color: textSecondaryColor }]}>
                          {match.description}
                        </Text>
                      ) : null}
                    </View>
                  );
                })
              ) : result.summary ? (
                <Text style={[styles.summaryText, { color: textColor }]}>{result.summary}</Text>
              ) : (
                <Text style={[styles.summaryText, { color: textSecondaryColor }]}>
                  Nessun risultato trovato.
                </Text>
              )}
            </View>
          )}

          {/* History Button */}
          <TouchableOpacity
            style={[styles.historyButton, { backgroundColor: cardColor }]}
            onPress={handleViewHistory}
            activeOpacity={0.8}
          >
            <IconSymbol ios_icon_name="clock.fill" android_material_icon_name="history" size={20} color={secondaryColor} />
            <Text style={[styles.historyButtonText, { color: textColor }]}>Vedi Storico</Text>
          </TouchableOpacity>

          {/* Logout Button */}
          <TouchableOpacity
            style={[styles.logoutButton, { backgroundColor: cardColor }]}
            onPress={() => {
              console.log('[Home] User tapped logout button');
              setLogoutModal(true);
            }}
            activeOpacity={0.8}
          >
            <Text style={[styles.logoutButtonText, { color: textColor }]}>Esci</Text>
          </TouchableOpacity>

          <View style={{ height: 120 }} />
        </ScrollView>

        {/* Error Modal */}
        <Modal
          visible={errorModal.visible}
          transparent
          animationType="fade"
          onRequestClose={() => setErrorModal({ visible: false, message: '' })}
        >
          <View style={styles.modalOverlay}>
            <View style={[styles.modalContent, { backgroundColor: cardColor }]}>
              <Text style={styles.modalEmoji}>⚠️</Text>
              <Text style={[styles.modalTitle, { color: textColor }]}>Attenzione</Text>
              <Text style={[styles.modalMessage, { color: textSecondaryColor }]}>
                {errorModal.message}
              </Text>
              <TouchableOpacity
                style={[styles.modalButton, { backgroundColor: secondaryColor }]}
                onPress={() => setErrorModal({ visible: false, message: '' })}
              >
                <Text style={[styles.modalButtonText, { color: colors.background }]}>OK</Text>
              </TouchableOpacity>
            </View>
          </View>
        </Modal>

        {/* Logout Confirmation Modal */}
        <Modal
          visible={logoutModal}
          transparent
          animationType="fade"
          onRequestClose={() => setLogoutModal(false)}
        >
          <View style={styles.modalOverlay}>
            <View style={[styles.modalContent, { backgroundColor: cardColor }]}>
              <Text style={styles.modalEmoji}>👋</Text>
              <Text style={[styles.modalTitle, { color: textColor }]}>Uscire dall'account?</Text>
              <Text style={[styles.modalMessage, { color: textSecondaryColor }]}>
                Sei sicuro di voler uscire dal tuo account?
              </Text>
              <View style={styles.modalButtons}>
                <TouchableOpacity
                  style={[styles.modalButtonHalf, { backgroundColor: textSecondaryColor }]}
                  onPress={() => setLogoutModal(false)}
                >
                  <Text style={[styles.modalButtonText, { color: colors.background }]}>Annulla</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[styles.modalButtonHalf, { backgroundColor: secondaryColor }]}
                  onPress={handleLogout}
                >
                  <Text style={[styles.modalButtonText, { color: colors.background }]}>Esci</Text>
                </TouchableOpacity>
              </View>
            </View>
          </View>
        </Modal>
      </SafeAreaView>
    </LinearGradient>
  );
}

const styles = StyleSheet.create({
  gradientContainer: { flex: 1 },
  container: { flex: 1 },
  scrollView: { flex: 1 },
  scrollContent: { padding: 20 },
