import React, { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  Platform,
  KeyboardAvoidingView,
  ScrollView,
  Modal,
} from "react-native";
import { useRouter } from "expo-router";
import { colors } from "@/styles/commonStyles";
import { LinearGradient } from "expo-linear-gradient";

type Mode = "signin" | "signup";

export default function AuthScreen() {
  const { signInWithEmail, signUpWithEmail, signInWithGoogle, user } = useAuth();
  const [mode, setMode] = useState<Mode>("signin");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(false);
  const [errorModal, setErrorModal] = useState<{ visible: boolean; message: string }>({
    visible: false,
    message: "",
  });
  const router = useRouter();

  // Navigate after successful login — let AuthGuard handle it
  useEffect(() => {
    if (user) {
      console.log("[Auth] User logged in, navigating to home");
      router.replace("/(tabs)/(home)");
    }
  }, [user]);

  const showError = (message: string) => {
    console.log("[Auth] Showing error:", message);
    setErrorModal({ visible: true, message });
  };

  const handleEmailAuth = async () => {
    console.log(`[Auth] User tapped ${mode} button with email:`, email);

    if (!email || !password) {
      showError("Inserisci email e password.");
      return;
    }

    if (mode === "signup" && !name) {
      showError("Inserisci il tuo nome.");
      return;
    }

    setLoading(true);
    try {
      if (mode === "signin") {
        await signInWithEmail(email, password);
        console.log("[Auth] Email sign-in successful");
      } else {
        await signUpWithEmail(email, password, name);
        console.log("[Auth] Email sign-up successful");
      }
      // Navigation handled by useEffect above
    } catch (error: any) {
      console.error("[Auth] Email auth error:", error);
      showError(error?.message || "Si è verificato un errore. Riprova.");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleAuth = async () => {
    console.log("[Auth] User tapped Google sign-in button");
    setLoading(true);
    try {
      await signInWithGoogle();
      console.log("[Auth] Google auth initiated");
      // Navigation handled by useEffect above
    } catch (error: any) {
      console.error("[Auth] Google auth error:", error);
      showError(error?.message || "Errore durante l'accesso con Google. Riprova.");
      setLoading(false);
    }
  };

  const isSignIn = mode === "signin";
  const modeText = isSignIn ? "Accedi" : "Registrati";
  const switchText = isSignIn ? "Non hai un account?" : "Hai già un account?";
  const switchAction = isSignIn ? "Registrati" : "Accedi";

  return (
    <LinearGradient
      colors={[colors.background, colors.backgroundDark]}
      style={styles.container}
      start={{ x: 0, y: 0 }}
      end={{ x: 1, y: 1 }}
    >
      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : "height"}
        style={styles.keyboardView}
      >
        <ScrollView
          contentContainerStyle={styles.scrollContent}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >
          <View style={styles.header}>
            <View style={styles.emojiRow}>
              <Text style={styles.emoji}>🤔</Text>
              <Text style={styles.emoji}>👥</Text>
              <Text style={styles.emoji}>✨</Text>
            </View>
            <Text style={[styles.title, { color: colors.text }]}>Chi ti somiglia?</Text>
            <Text style={[styles.subtitle, { color: colors.textSecondary }]}>
              {isSignIn ? "Bentornato!" : "Crea il tuo account"}
            </Text>
          </View>

          <View style={styles.form}>
            {!isSignIn && (
              <TextInput
                style={[styles.input, { backgroundColor: colors.card, color: colors.text, borderColor: colors.border }]}
                placeholder="Nome"
                placeholderTextColor={colors.textSecondary}
                value={name}
                onChangeText={setName}
                autoCapitalize="words"
                editable={!loading}
              />
            )}

            <TextInput
              style={[styles.input, { backgroundColor: colors.card, color: colors.text, borderColor: colors.border }]}
              placeholder="Email"
              placeholderTextColor={colors.textSecondary}
              value={email}
              onChangeText={setEmail}
              keyboardType="email-address"
              autoCapitalize="none"
              autoComplete="email"
              editable={!loading}
            />

            <TextInput
              style={[styles.input, { backgroundColor: colors.card, color: colors.text, borderColor: colors.border }]}
              placeholder="Password"
              placeholderTextColor={colors.textSecondary}
              value={password}
              onChangeText={setPassword}
              secureTextEntry
              autoCapitalize="none"
              autoComplete="password"
              editable={!loading}
            />

            <TouchableOpacity
              style={styles.primaryButton}
              onPress={handleEmailAuth}
              disabled={loading}
              activeOpacity={0.8}
            >
              <LinearGradient
                colors={[colors.secondary, colors.accent]}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 0 }}
                style={styles.buttonGradient}
              >
                {loading ? (
                  <ActivityIndicator color={colors.background} />
                ) : (
                  <Text style={[styles.buttonText, { color: colors.background }]}>{modeText}</Text>
                )}
              </LinearGradient>
            </TouchableOpacity>

            <View style={styles.divider}>
              <View style={[styles.dividerLine, { backgroundColor: colors.textSecondary }]} />
              <Text style={[styles.dividerText, { color: colors.textSecondary }]}>oppure</Text>
              <View style={[styles.dividerLine, { backgroundColor: colors.textSecondary }]} />
            </View>

            <TouchableOpacity
              style={[styles.socialButton, { backgroundColor: colors.card }]}
              onPress={handleGoogleAuth}
              disabled={loading}
              activeOpacity={0.8}
            >
              <Text style={styles.googleIcon}>G</Text>
              <Text style={[styles.socialButtonText, { color: colors.text }]}>
                Continua con Google
              </Text>
            </TouchableOpacity>

            <TouchableOpacity
              style={styles.switchButton}
              onPress={() => {
                console.log('[Auth] User toggled mode to:', isSignIn ? 'signup' : 'signin');
                setMode(isSignIn ? "signup" : "signin");
              }}
              disabled={loading}
            >
              <Text style={[styles.switchText, { color: colors.textSecondary }]}>
                {switchText}{" "}
                <Text style={[styles.switchAction, { color: colors.secondary }]}>
                  {switchAction}
                </Text>
              </Text>
            </TouchableOpacity>
          </View>
        </ScrollView>
      </KeyboardAvoidingView>

      {/* Error Modal */}
      <Modal
        visible={errorModal.visible}
        transparent
        animationType="fade"
        onRequestClose={() => setErrorModal({ visible: false, message: "" })}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, { backgroundColor: colors.card }]}>
            <Text style={styles.modalEmoji}>⚠️</Text>
            <Text style={[styles.modalTitle, { color: colors.text }]}>Attenzione</Text>
            <Text style={[styles.modalMessage, { color: colors.textSecondary }]}>
              {errorModal.message}
            </Text>
            <TouchableOpacity
              style={[styles.modalButton, { backgroundColor: colors.secondary }]}
              onPress={() => setErrorModal({ visible: false, message: "" })}
            >
              <Text style={[styles.modalButtonText, { color: colors.background }]}>OK</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </LinearGradient>
  );
}

